"""26 unique kid-friendly stage concepts. Each: (bg css, light, visual html). Interactive via data-attrs + concepts.js."""
C = {}
def add(slug, bg, light, html): C[slug] = (bg, light, html)

# 1 English Phonics: tap blocks -> word
add('english-phonics', 'linear-gradient(135deg,#FFF7D6,#FFE08A)', 0, '''<div class="cx blocks-word" data-words="A:Apple 🍎,B:Ball ⚽,C:Cat 🐱,D:Dog 🐶,E:Egg 🥚,F:Fish 🐟">
<div class="bw-row">'''+''.join(f'<button class="bw" style="--c:{c};--r:{r}deg">{l}</button>' for l,c,r in zip('ABCDEF',['#FF6B6B','#4D96FF','#6BCB77','#FFB703','#C77DFF','#FF8FAB'],[-6,4,-3,5,-5,3]))+'''</div><p class="bw-out">Tap a block!</p></div>''')
add('phonics-english-adults', 'linear-gradient(135deg,#EEF2FF,#C7D2FE)', 0, '''<div class="cx sound-wave"><div class="sw-card"><b>sh</b><span>as in <i>ship</i> 🚢</span></div><div class="sw-bars">'''+''.join(f'<i style="--d:{i*0.08:.2f}s"></i>' for i in range(22))+'''</div><div class="sw-tags"><span>ch</span><span>th</span><span>ai</span><span>oo</span></div></div>''')
