add('phonics-tamil-adults', 'linear-gradient(135deg,#7C2D12,#C2410C)', 1, '''<div class="cx tamil-board"><div class="tb-grid">'''+''.join(f'<span style="--d:{i*.12:.2f}s">{l}</span>' for i,l in enumerate('கஙசஞடணதநபமயர'))+'''</div><p>Teach Tamil sounds with confidence</p></div>''')
