add('aari-work', 'radial-gradient(circle at 40% 50%,#9F1239,#4C0519)', 1, '''<div class="cx hoop"><svg viewBox="0 0 220 220"><circle cx="110" cy="110" r="96" fill="#FFF7ED" stroke="#C08457" stroke-width="12"/><g fill="none" stroke="#F5B301" stroke-width="3" stroke-linecap="round" class="zari"><path pathLength="1" d="M110 60c18 0 18 30 0 50-18-20-18-50 0-50z"/><path pathLength="1" d="M110 110c30-10 46 12 30 34-22 4-30-14-30-34z"/><path pathLength="1" d="M110 110c-30-10-46 12-30 34 22 4 30-14 30-34z"/></g>'''+''.join(f'<circle cx="{x}" cy="{y}" r="4" fill="#F472B6" class="bead2" style="animation-delay:{1.6+i*.15:.2f}s"/>' for i,(x,y) in enumerate([(110,112),(86,70),(134,70),(70,130),(150,130),(110,160)]))+'''</svg><span class="needle">🪡</span></div>''')
add('embroidery', 'linear-gradient(135deg,#FDF2F8,#FBCFE8)', 0, '''<div class="cx xstitch"><div class="xs-grid">'''+''.join(f'<i class="{"on" if c=="#" else ""}" style="--d:{i*.04:.2f}s"></i>' for i,c in enumerate(''.join(['.##...##.','#########','#########','.#######.','..#####..','...###...','....#....'])))+'''</div><p>Stitch by stitch 💗</p></div>''')
# 8 Language
