add('spoken-english', 'linear-gradient(135deg,#ECFEFF,#CFFAFE)', 0, '''<div class="cx chat">'''+''.join(f'<p class="cb {s}" style="--d:{i*.9}s">{t}</p>' for i,(s,t) in enumerate([('l','Hi! What\'s your name? 👋'),('r','I\'m Priya. Nice to meet you!'),('l','What do you like to do?'),('r','I love dancing and reading! 💃📚')]))+'''</div>''')
add('creative-writing', 'linear-gradient(135deg,#FEF3C7,#FCD34D)', 0, '''<div class="cx book"><div class="bk-l"><p class="type">Once upon a time, a little dragon wanted to learn to fly…</p></div><div class="bk-r"><span class="drg">🐉</span><span class="sp s1">✨</span><span class="sp s2">⭐</span><span class="sp s3">🌙</span></div></div>''')
