# 10 Code Crackers: each different
add('web-mobile-app-development', 'linear-gradient(135deg,#0F172A,#1E3A8A)', 1, '''<div class="cx browser"><div class="bz-bar"><i></i><i></i><i></i><span>myapp.com</span></div><div class="bz-body"><div class="bz-code">&lt;h1&gt;Hello!&lt;/h1&gt;<br>&lt;button&gt;Tap me&lt;/button&gt;</div><div class="bz-out"><b>Hello!</b><button data-tap>Tap me</button><p class="bz-n">🎉 0 taps</p></div></div></div>''')
add('video-editing', 'linear-gradient(135deg,#18181B,#3F3F46)', 1, '''<div class="cx vtl"><div class="vt-screen"><span class="vt-f">🎬</span><span class="vt-rec">● REC</span></div><div class="vt-track">'''+''.join(f'<i style="--w:{w}%;--c:{c}"></i>' for w,c in [(26,'#F43F5E'),(18,'#8B5CF6'),(30,'#06B6D4'),(22,'#F59E0B')])+'''<span class="vt-head"></span></div></div>''')
add('graphic-design', 'linear-gradient(135deg,#FFF1F2,#FECDD3)', 0, '''<div class="cx poster2" data-poster><div class="pz2"><span class="pz-sh"></span><b>SUMMER<br>FEST</b></div><div class="pz-cols"><button style="--c:#F43F5E"></button><button style="--c:#8B5CF6"></button><button style="--c:#06B6D4"></button><button style="--c:#F59E0B"></button></div></div>''')
add('ux-ui-design', 'linear-gradient(135deg,#F0FDFA,#99F6E4)', 0, '''<div class="cx phone2"><div class="ph2"><i class="w1"></i><i class="w2"></i><i class="w3"></i><i class="w4"></i><i class="w5"></i></div><p>Wireframe → beautiful app ✨</p></div>''')
add('digital-marketing', 'linear-gradient(135deg,#F0FDF4,#BBF7D0)', 0, '''<div class="cx growth"><div class="gr-bars">'''+''.join(f'<i style="--h:{h}%;--d:{i*.15:.2f}s"></i>' for i,h in enumerate([20,32,28,48,60,74,92]))+'''</div><div class="gr-likes"><span>❤ 1.2k</span><span>👁 8.4k</span><span>📈 +64%</span></div></div>''')
add('ai-tools-tech', 'radial-gradient(circle at 50% 40%,#312E81,#0F0A2E)', 1, '''<div class="cx aichat"><p class="ac q">Draw a cat astronaut 🐱🚀</p><p class="ac a"><span class="dots3"><i></i><i></i><i></i></span><span class="ac-r">🐱‍🚀 Here you go! Remember: always check AI work.</span></p></div>''')
add('project-management', 'linear-gradient(135deg,#F8FAFC,#E2E8F0)', 0, '''<div class="cx kb2"><div><b>To do</b><i class="t1">Plan</i></div><div><b>Doing</b><i class="t2">Design</i></div><div><b>Done ✅</b><i class="t3">Launch 🎉</i></div><span class="mv-card">Build</span></div>''')
